perl -e '
use strict;
use warnings;
use File::Find;

my $root = "/bench/repo";
my $module = "github.com/usememos/memos";

# 1. Collect all func/method declarations under internal/
my @symbols;  # {name, path, pkg, kind, recv}

sub parse_pkg {
    my ($file) = @_;
    open my $fh, "<", $file or return "";
    my $pkg = "";
    while (<$fh>) {
        if (/^package\s+(\w+)/) { $pkg = $1; last; }
    }
    close $fh;
    return $pkg;
}

find({
    wanted => sub {
        return unless /\.go$/;
        return unless $File::Find::name =~ m{^$root/internal/};
        my $file = $File::Find::name;
        my $pkg = parse_pkg($file);
        open my $fh, "<", $file or return;
        my $line_no = 0;
        while (<$fh>) {
            $line_no++;
            # func Name( or func (recv) Name(
            if (/^func\s+(?:\([^)]*\)\s+)?([A-Za-z_]\w*)\s*\(/) {
                my $name = $1;
                my $recv = "";
                if (/^func\s+\(([^)]*)\)\s+/) {
                    $recv = $1;
                }
                push @symbols, {
                    name => $name,
                    path => $file,
                    pkg => $pkg,
                    recv => $recv,
                    decl_line => $line_no,
                };
            }
        }
        close $fh;
    },
    no_chdir => 1,
}, "$root/internal");

# Build import alias map per file: alias -> import path
sub get_imports {
    my ($file) = @_;
    my %imports;
    open my $fh, "<", $file or return %imports;
    my $in_import = 0;
    while (<$fh>) {
        if (/^import\s+\(\s*$/) { $in_import = 1; next; }
        if ($in_import) {
            last if /^\)/;
            if (/^\s*"([^"]+)"/) {
                my $path = $1;
                my $alias = (split m{/}, $path)[-1];
                $imports{$alias} = $path;
            } elsif (/^\s*(\w+)\s+"([^"]+)"/) {
                $imports{$1} = $2;
            }
            next;
        }
        if (/^import\s+"([^"]+)"/) {
            my $path = $1;
            my $alias = (split m{/}, $path)[-1];
            $imports{$alias} = $path;
        }
        last if /^[^\/\s]/ && !/^import/ && !/^package/;
    }
    close $fh;
    return %imports;
}

# Map package path -> list of symbol names
my %pkg_funcs;  # full import path -> {name -> 1}
for my $s (@symbols) {
    # derive import path from file
    my ($dir) = $s->{path} =~ m{^(.*)/[^/]+\.go$};
    my $rel = substr($dir, length("$root/"));
    my $import_path = "$module/$rel";
    $pkg_funcs{$import_path}{$s->{name}} = 1;
}

# Also same-package: dir -> names
my %dir_funcs;
for my $s (@symbols) {
    my ($dir) = $s->{path} =~ m{^(.*)/[^/]+\.go$};
    $dir_funcs{$dir}{$s->{name}} = 1;
}

# 2. Count call sites for each symbol
my %fanin;  # key: path|name -> count
my %caller_files; # track unique caller files

for my $s (@symbols) {
    my $key = "$s->{path}|$s->{name}";
    $fanin{$key} = 0;
    $caller_files{$key} = {};
}

# Collect all go files in repo
my @all_go;
find({
    wanted => sub {
        push @all_go, $File::Find::name if /\.go$/;
    },
    no_chdir => 1,
}, $root);

for my $file (@all_go) {
    my ($file_dir) = $file =~ m{^(.*)/[^/]+$};
    my %imports = get_imports($file);

    open my $fh, "<", $file or next;
    my $line_no = 0;
    while (<$fh>) {
        $line_no++;
        # Skip comments roughly
        next if /^\s*\/\//;

        for my $s (@symbols) {
            my $key = "$s->{path}|$s->{name}";
            my $name = $s->{name};
            my ($sym_dir) = $s->{path} =~ m{^(.*)/[^/]+\.go$};
            my $rel = substr($sym_dir, length("$root/"));
            my $import_path = "$module/$rel";

            # Skip declaration line
            next if $file eq $s->{path} && $line_no == $s->{decl_line};

            my $matched = 0;

            if ($file_dir eq $sym_dir) {
                # Same package: direct call Name(
                if (/\b\Q$name\E\s*\(/) {
                    $matched = 1;
                }
            } else {
                # Qualified call via import alias
                for my $alias (keys %imports) {
                    next unless $imports{$alias} eq $import_path;
                    if (/\b\Q$alias\E\.\Q$name\E\s*\(/) {
                        $matched = 1;
                        last;
                    }
                }
            }

            # Method calls: .Name(
            if (!$matched && $s->{recv}) {
                if (/\.\Q$name\E\s*\(/) {
                    $matched = 1;
                }
            }

            if ($matched) {
                $fanin{$key}++;
                $caller_files{$key}{$file} = 1;
            }
        }
    }
    close $fh;
}

# Sort by fanin
my @sorted = sort { $fanin{$b} <=> $fanin{$a} } keys %fanin;

print "Top 30 by call-site count:\n";
for my $i (0..29) {
    last unless $sorted[$i];
    my ($path, $name) = split /\|/, $sorted[$i], 2;
    my $rel = substr($path, length("$root/"));
    my $callers = scalar keys %{$caller_files{$sorted[$i]}};
    printf "%4d calls (%3d files)  %s  %s\n", $fanin{$sorted[$i]}, $callers, $name, $rel;
}
print "\nTotal symbols: ", scalar(@symbols), "\n";
'

