                is_method => 1, recv_type => $recv_type, decl_line => $line_no };
        } elsif (/^func\s+([A-Za-z_]\w*)\s*\(/) {
            my $name = $1;
            my ($dir) = $file =~ m{^(.*)/[^/]+\.go$};
            my $rel = substr($dir, length("$root/"));
