                is_method => 0, recv_type => "", decl_line => $line_no };
        }
    }
    close $fh;
}

sub get_imports {
    my ($file) = @_;
    my %imports;
    open my $fh, "<", $file or return %imports;
    my $in_import = 0;
    while (<$fh>) {
        if (/^import\s+\(\s*$/) { $in_import = 1; next; }
        if ($in_import) {
            last if /^\)/;
            if (/^\s*"([^"]+)"/) {
                my $path = $1; my $alias = (split m{/}, $path)[-1]; $imports{$alias} = $path;
            } elsif (/^\s*(\w+)\s+"([^"]+)"/) { $imports{$1} = $2; }
