        }
        last if /^[^\/\s]/ && !/^import/ && !/^package/;
    }
    close $fh;
    return %imports;
}

# Build recv_type -> method names per import path (for typed method calls)
my %type_methods; # import_path|Type -> {method -> symbol idx}
my %sym_idx;
for my $i (0..$#symbols) {
    my $s = $symbols[$i];
    $sym_idx{"$s->{path}|$s->{name}|$s->{recv_type}"} = $i;
    if ($s->{is_method} && $s->{recv_type}) {
        $type_methods{"$s->{import_path}|$s->{recv_type}"}{$s->{name}} = $i;
    }
}

my @counts = (0) x @symbols;
