    my ($file_dir) = $file =~ m{^(.*)/[^/]+$};
    my %imports = get_imports($file);
    # reverse: import_path -> [aliases]
    my %path_aliases;
    for my $alias (keys %imports) {
        push @{$path_aliases{$imports{$alias}}}, $alias;
    }

    open my $fh, "<", $file or next;
    my $line_no = 0;
    while (<$fh>) {
        $line_no++;
        next if /^\s*\/\//;

        for my $i (0..$#symbols) {
            my $s = $symbols[$i];
            next if $file eq $s->{path} && $line_no == $s->{decl_line};
            my $name = $s->{name};
