                    if (/\b\Q$alias\E\.\Q$rt\E\.\Q$name\E\s*\(/) { $matched = 1; last; }
                }
            }

            if ($matched) {
                $counts[$i]++;
                $caller_files[$i]{$file} = 1;
            }
        }
    }
    close $fh;
}

my @order = sort { $counts[$b] <=> $counts[$a] } 0..$#symbols;
print "Top 30 (strict package-level + typed method calls):\n";
for my $rank (0..29) {
    my $i = $order[$rank];
    last unless defined $i;
    my $s = $symbols[$i];
    my $rel = substr($s->{path}, length("$root/"));
    my $kind = $s->{is_method} ? "method($s->{recv_type})" : "func";
    my $callers = scalar keys %{$caller_files[$i]};
    printf "%4d calls (%3d files)  %s %s  %s\n", $counts[$i], $callers, $kind, $s->{name}, $rel;
}
