use strict; use warnings;
my $root="/bench/repo"; my $module="github.com/usememos/memos";
my @all_go = split /\n/, `find $root -name "*.go" 2>/dev/null`;
my $target="NewEngine"; my $dir="$root/internal/filter"; my $import="$module/internal/filter";
sub get_imports { my ($f)=@_; my %i; open my $fh,"<",$f or return %i; my $in=0; while(<$fh>){ if(/^import\s+\(\s*$/){$in=1;next} if($in){last if/^\)/; if(/^\s*"([^"]+)"/){my $p=$1;$i{(split m{/},$p)[-1]}=$p} elsif(/^\s*(\w+)\s+"([^"]+)"/){$i{$1}=$2} next} if(/^import\s+"([^"]+)"/){my $p=$1;$i{(split m{/},$p)[-1]}=$p} last if /^[^\/\s]/&&!/^import/&&!/^package/} close $fh; return %i }
my %callers;
for my $file (@all_go) {
  my ($file_dir) = $file =~ m{^(.*)/[^/]+$};
  my %imports=get_imports($file); my %pa; for(keys %imports){push @{$pa{$imports{$_}}},$_}
  open my $fh,"<",$file or next; my @lines=<$fh>; close $fh; my $cur="<top>";
  for my $ln (1..@lines){ my $line=$lines[$ln-1]; if($line=~/^func\s+(?:\([^)]*\)\s+)?([A-Za-z_]\w*)\s*\(/){$cur="$file:$1"}
    next if $line=~/^\s*\/\// || $line=~/^func\s+/;
    my $hit=0;
    if($file_dir eq $dir){ $hit=1 if $line=~/\b\Q$target\E\s*\(/ }
    else { for my $a(@{$pa{$import}//[]}){ if($line=~/\b\Q$a\E\.\Q$target\E\s*\(/){$hit=1;last} } }
    if($hit){ $callers{$cur}=1; print "$file:$ln: $line" if 0; }
  }
}
print scalar(keys %callers), " callers\n";
print "$_\n" for sort keys %callers;
'
